List<Order> findAll() {
  List<Order> result = new ArrayList<>();
  try (Statement stmt = connection.createStatement();
       ResultSet rs = stmt.executeQuery("SELECT id, status FROM orders ORDER BY id")) {
    while (rs.next()) result.add(mapRow(rs));
    return result;
  } catch (SQLException e) { throw new RuntimeException(e); }
}

List<Order> findByStatus(String status) {
  List<Order> result = new ArrayList<>();
  try (PreparedStatement stmt = connection.prepareStatement("SELECT id, status FROM orders WHERE status = ? ORDER BY id")) {
    stmt.setString(1, status);
    try (ResultSet rs = stmt.executeQuery()) { while (rs.next()) result.add(mapRow(rs)); }
    return result;
  } catch (SQLException e) { throw new RuntimeException(e); }
}

