static String generateStatusReport(OrderJdbcDao dao) {
  StringBuilder sb = new StringBuilder();
  int suma = 0;
  for (String s : List.of("NEW", "SHIPPED", "CANCELLED")) {
    int n = dao.findByStatus(s).size();
    suma += n;
    sb.append(s).append(": ").append(n).append("\n");
  }
  sb.append("suma: ").append(suma).append(" (findAll: ").append(dao.findAll().size()).append(")");
  return sb.toString();
}

